mapper.select:
SELECT id
FROM b_marketing_transfer_info
WHERE api_code = #{apiCode}

  AND create_time >= #{validStartDate}
  AND create_time <= #{validEndDate}

order by create_time,id
LIMIT ${page * pageSize}, ${pageSize}

select count(id)
from b_marketing_transfer_info
where api_code = #{apiCode}
    AND create_time >= #{startDate} and create_time < #{endDate} 
  and status = 1

SELECT
    request_id
FROM
    b_marketing_transfer_info
WHERE
    `status` in(2, 4)
  and api_code =#{apiCode}
  and date_format(create_time, '%Y-%m-%d') = #{bizDate}
  and last =#{last}
    limit 1

select
    *
from b_marketing_transfer_info
where api_code = #{apiCode}
  and request_id = #{requestId}
limit 1
